function renderActionFeedback(state='idle'){const el=$('actionFeedback');if(!el)return;if(actionFeedbackHideTimer){clearTimeout(actionFeedbackHideTimer);actionFeedbackHideTimer=null;}if(state==='pending'||pendingMutationCount>0){el.hidden=false;el.dataset.state='pending';el.textContent=pendingMutationCount>1?`작업 처리 중 · ${pendingMutationCount}건`:'작업 처리 중';return;}if(state==='done'){el.hidden=false;el.dataset.state='done';el.textContent='응답 수신';actionFeedbackHideTimer=setTimeout(()=>{if(pendingMutationCount===0){el.hidden=true;el.dataset.state='idle';}},900);return;}el.hidden=true;el.dataset.state='idle';}
function dismissFeedback(id){feedbackQueue=feedbackQueue.filter(item=>item.id!==id);const timer=feedbackTimers.get(id);if(timer)clearTimeout(timer);feedbackTimers.delete(id);renderFeedback();}
function dismissFeedbackByKey(key){const ids=feedbackQueue.filter(item=>item.dedupeKey===key).map(item=>item.id);for(const id of ids)dismissFeedback(id);const banner=$('notice');if(banner?.dataset.feedbackKey===key){banner.textContent='';banner.classList.remove('error');delete banner.dataset.tone;delete banner.dataset.feedbackKey;}}
function renderFeedback(){const stack=$('toastStack');if(!stack)return;stack.replaceChildren(...feedbackQueue.map(item=>{const toast=document.createElement('article');toast.className=`feedback-toast feedback-${item.tone}`;toast.dataset.feedbackId=item.id;toast.setAttribute('role',feedbackAriaRole(item.tone));const icon=document.createElement('span');icon.className='feedback-toast-icon';icon.textContent={success:'✓',error:'!',warning:'!',info:'i'}[item.tone]||'i';const copy=document.createElement('div');copy.className='feedback-toast-copy';const title=document.createElement('strong');title.textContent=item.title;const message=document.createElement('p');message.textContent=item.message;copy.append(title,message);if(item.count>1){const repeated=document.createElement('small');repeated.textContent=`같은 알림 ${item.count}회`;copy.append(repeated);}const close=document.createElement('button');close.type='button';close.className='feedback-toast-close';close.dataset.feedbackDismiss=item.id;close.setAttribute('aria-label','알림 닫기');close.textContent='×';toast.append(icon,copy,close);return toast;}));}
function pushFeedback(message,{tone='info',title='',sticky=false,timeoutMs,showBanner=false,dedupeKey=''}={}){const entry=createDashboardFeedback({id:`feedback-${Date.now()}-${++feedbackSequence}`,message,tone,title,sticky,timeoutMs,dedupeKey});if(!entry)return;const previousIds=new Set(feedbackQueue.map(item=>item.id));feedbackQueue=upsertDashboardFeedback(feedbackQueue,entry,{limit:4});for(const id of previousIds){if(!feedbackQueue.some(item=>item.id===id)){const timer=feedbackTimers.get(id);if(timer)clearTimeout(timer);feedbackTimers.delete(id);}}const active=feedbackQueue.find(item=>item.dedupeKey===entry.dedupeKey);if(active&&!active.sticky){const old=feedbackTimers.get(active.id);if(old)clearTimeout(old);feedbackTimers.set(active.id,setTimeout(()=>dismissFeedback(active.id),active.timeoutMs));}renderFeedback();const banner=$('notice');if(banner){if(showBanner||tone==='error'){banner.textContent=entry.message;banner.classList.toggle('error',tone==='error');banner.dataset.tone=tone;banner.dataset.feedbackKey=entry.dedupeKey;}else{banner.textContent='';banner.classList.remove('error');delete banner.dataset.tone;delete banner.dataset.feedbackKey;}}}
