async function releaseRefresh(){if(releaseLoading)return;releaseLoading=true;try{releaseData=await request('/api/release');renderRelease();}catch(error){notice(error.message,true);}finally{releaseLoading=false;}}
async function verifyReleaseFile(){const file=$('releaseBundleFile').files?.[0];if(!file){notice('업데이트 JSON 패키지를 선택해 주세요.',true);return;}if(file.size>8*1024*1024){notice('업데이트 패키지가 너무 큽니다. 8MB 이하 JSON을 사용해 주세요.',true);return;}busy=true;renderRelease();try{const text=await file.text();let bundle;try{bundle=JSON.parse(text);}catch{throw Error('업데이트 JSON 파일 형식을 읽지 못했습니다.');}releaseVerification=await request('/api/release/verify',{bundle});await releaseRefresh();notice(`업데이트 패키지 검증 완료 · 대상 ${releaseVerification.targetVersion}`);}catch(error){releaseVerification=error.data?.checks?{...error.data,ok:false}:{ok:false,checks:[{status:'fail',label:'패키지 검증',detail:error.message}]};notice(error.message,true);}finally{busy=false;renderRelease();}}
async function applyRelease(){if(busy||releaseData?.state?.status!=='staged')return;try{const approval=await prepareGuard('apply-release',{},`검증된 코드 업데이트 ${releaseData.current?.version||appVersion} → ${releaseData.state.targetVersion}를 적용합니다. 운영 데이터 백업과 코드 롤백 스냅샷이 먼저 생성됩니다.`);if(!approval)return;busy=true;renderRelease();const result=await request('/api/release/apply',approval);notice(result.message||'업데이트 파일을 적용했습니다.');await Promise.all([releaseRefresh(),deploymentRefresh()]);}catch(error){notice(error.message,true);}finally{busy=false;renderRelease();}}
async function rollbackRelease(){if(busy||!releaseData?.state?.releaseId)return;try{const approval=await prepareGuard('rollback-release',{},`릴리스 ${releaseData.state.releaseId}의 변경 파일을 이전 상태로 복원합니다.`);if(!approval)return;busy=true;renderRelease();const result=await request('/api/release/rollback',approval);notice(result.message||'이전 코드 파일을 복원했습니다.');await releaseRefresh();}catch(error){notice(error.message,true);}finally{busy=false;renderRelease();}}
async function runReleaseSmoke(){if(busy)return;busy=true;renderRelease();try{const result=await request('/api/release/smoke',{});notice(result.status==='pass'?'Smoke Test를 통과했습니다.':'Smoke Test 실패 항목이 있습니다.',result.status!=='pass');await releaseRefresh();}catch(error){notice(error.message,true);}finally{busy=false;renderRelease();}}
async function trustReleaseKey(candidate=false){if(busy)return;const key=candidate?releaseVerification?.signature?.candidateKey:null,publicKeyPem=key?.publicKeyPem||$('releaseTrustPem').value.trim(),name=key?.name||$('releaseTrustName').value.trim()||'사용자 릴리스 키';if(!publicKeyPem){notice('Ed25519 공개키 PEM을 입력해 주세요.',true);return;}try{const approval=await prepareGuard('trust-release-key',{publicKeyPem,name},`릴리스 공개키 "${name}"을 신뢰 목록에 추가합니다. 이후 이 키가 서명한 v3 업데이트를 신뢰하게 됩니다.`);if(!approval)return;busy=true;renderRelease();const result=await request('/api/release/trust/key',{publicKeyPem,name,...approval});if(releaseData)releaseData.trust=result.trust;$('releaseTrustPem').value='';$('releaseTrustName').value='';notice(`릴리스 공개키를 신뢰했습니다 · ${result.added.keyId}`);await releaseRefresh();if(candidate&&$('releaseBundleFile').files?.[0])await verifyReleaseFile();}catch(error){notice(error.message,true);}finally{busy=false;renderRelease();}}
async function removeReleaseKey(keyId){if(busy)return;const key=releaseData?.trust?.keys?.find(item=>item.keyId===keyId);if(!key||key.builtin)return;try{const approval=await prepareGuard('remove-release-key',{keyId},`릴리스 신뢰 키 "${key.name}" (${keyId})를 삭제합니다.`);if(!approval)return;busy=true;renderRelease();const result=await request('/api/release/trust/remove',{keyId,...approval});if(releaseData)releaseData.trust=result.trust;notice('릴리스 신뢰 키를 삭제했습니다.');await releaseRefresh();}catch(error){notice(error.message,true);}finally{busy=false;renderRelease();}}
async function saveReleaseTrustPolicy(){if(busy)return;const policy=$('releaseTrustPolicy').value,current=releaseData?.trust?.policy;if(policy===current){notice('Trust Policy가 이미 같은 값입니다.');return;}try{const approval=await prepareGuard('set-release-policy',{policy},`릴리스 Trust Policy를 ${policy.toUpperCase()}로 변경합니다.${policy==='required'?' 이후 v1/v2 무서명 패키지는 차단됩니다.':''}`);if(!approval)return;busy=true;renderRelease();const result=await request('/api/release/trust/policy',{policy,...approval});if(releaseData)releaseData.trust=result.trust;markDirtyGroupClean('release-trust-policy');notice(`Trust Policy를 ${policy.toUpperCase()}로 변경했습니다.`);await releaseRefresh();}catch(error){notice(error.message,true);}finally{busy=false;renderRelease();}}

