 $('discordPolicyBadge').textContent=!baseline?'기준선 없음':comparison.status==='drift'?(maintenanceActive?'DRIFT · 점검':ackMatches?'DRIFT · 확인됨':'DRIFT'):comparison.status==='pass'?'정상':'대기';$('discordPolicyBadge').classList.toggle('warn',comparison.status==='drift'&&!maintenanceActive&&!ackMatches);
 $('discordPolicyBaseline').textContent=baseline?baseline.digest.slice(0,12):'—';$('discordPolicyBaselineTime').textContent=baseline?new Date(baseline.capturedAt).toLocaleString('ko-KR'):'저장 전';
 $('discordPolicyDrift').textContent=baseline?String(counts.total??0):'—';$('discordPolicySafe').textContent=baseline?String((comparison.safeActions||[]).length):'—';$('discordPolicyAttribution').textContent=attribution.available?'사용 가능':'선택 기능';
 const diff=$('discordPolicyDiff');if(diff)diff.innerHTML=!baseline?'<p class="empty">현재 Discord 구성을 먼저 감사한 뒤 정상 기준선을 저장하세요.</p>':items.length?items.map(item=>{const actor=item.actor?`<small class="discord-policy-actor">변경 주체: ${esc(item.actor.name||'알 수 없음')} · ${esc(item.actor.action||'변경')} · ${item.actor.at?esc(new Date(item.actor.at).toLocaleString('ko-KR')):''}</small>`:'';return `<div class="discord-policy-diff ${esc(item.kind||'manual')}"><span class="policy-kind">${item.kind==='safe'?'SAFE':'MANUAL'}</span><div><strong>${esc(item.title||item.id)}</strong><small>${esc(item.detail||'')}</small>${actor}</div></div>`;}).join(''):'<div class="check-row pass"><span class="check-icon">✓</span><div><strong>기준선과 일치</strong><small>저장된 정상 기준선과 현재 Discord 설정 차이가 없습니다.</small></div></div>';
 $('discordPolicyJournalCount').textContent=`${journal.length}건`;$('discordPolicyJournal').innerHTML=journal.length?journal.slice(0,100).map(entry=>{const actors=[...new Set((entry.items||[]).map(item=>item.actor?.name).filter(Boolean))];const label=entry.type==='baseline-captured'?'BASELINE':entry.type?.startsWith('maintenance')?'MAINT':entry.type?.includes('ack')?'ACK':entry.status==='pass'?'CLEARED':'DRIFT';return `<div class="audit-row"><div><span class="audit-category">${label}</span><strong>${esc(entry.summary)}</strong><small>${esc(new Date(entry.at).toLocaleString('ko-KR'))}${actors.length?` · ${esc(actors.join(', '))}`:''}</small></div></div>`;}).join(''):'<p class="empty">아직 기준선 변경 이력이 없습니다.</p>';
 const monitorLabels={idle:'대기',pass:'정상',warn:'DRIFT',fail:'점검 오류'},monitorStatus=!baseline?'idle':monitorState.lastStatus||'idle';$('discordPolicyMonitorBadge').textContent=!monitor.enabled?'OFF':maintenanceActive?'MAINTENANCE':monitorLabels[monitorStatus]||monitorStatus;$('discordPolicyMonitorBadge').classList.toggle('warn',!maintenanceActive&&(monitorStatus==='warn'||monitorStatus==='fail'));$('discordPolicyMonitorState').textContent=monitor.enabled?'ON':'OFF';$('discordPolicyMonitorFailure').textContent=monitorState.lastError?`오류 ${monitorState.consecutiveFailures||1}회 · ${monitorState.lastError}`:`${monitor.intervalMinutes||5}분 간격`;$('discordPolicyMonitorLastRun').textContent=monitorState.lastRunAt?new Date(monitorState.lastRunAt).toLocaleTimeString('ko-KR'):'—';$('discordPolicyMonitorNextRun').textContent=monitor.enabled&&monitorState.nextRunAt?new Date(monitorState.nextRunAt).toLocaleTimeString('ko-KR'):'—';
 const routeLabels={off:'OFF',manual:'MANUAL',all:'ALL'};$('discordPolicyMonitorAlert').textContent=routeLabels[monitor.alertMode]||'OFF';$('discordPolicyMonitorAlertAt').textContent=monitorState.lastAlertError?`전송 실패 · ${monitorState.lastAlertError}`:monitorState.lastAlertAt?`최근 ${new Date(monitorState.lastAlertAt).toLocaleTimeString('ko-KR')}`:'상태 변화 시 1회';
