async function clearDiscordPolicyAck(){if(discordPolicyLoading||busy)return;discordPolicyLoading=true;renderDiscordPolicy();try{discordPolicyData=await request('/api/discord-policy/ack/clear',{});syncPolicyMonitorSnapshot();notice('Discord drift 확인 상태를 해제했습니다.');renderDiscordPolicy();renderCommandCenter();}catch(error){notice(error.message,true);}finally{discordPolicyLoading=false;renderDiscordPolicy();}}
async function captureDiscordPolicy(){if(discordPolicyLoading||busy)return;if(!confirm('현재 Discord 구성을 정상 기준선으로 저장할까요? 이후 변경은 이 상태와 비교됩니다.'))return;discordPolicyLoading=true;renderDiscordPolicy();try{discordPolicyData=await request('/api/discord-policy/baseline',{});syncPolicyMonitorSnapshot();notice('Discord 정상 기준선을 저장했습니다.');renderDiscordPolicy();renderCommandCenter();}catch(error){notice(error.message,true);}finally{discordPolicyLoading=false;renderDiscordPolicy();}}
async function restoreDiscordPolicy(){if(discordPolicyLoading||busy||!discordPolicyData?.comparison?.safeActions?.length)return;try{const actions=discordPolicyData.comparison.safeActions;const approval=await prepareGuard('restore-discord-baseline',{},`기준선에서 벗어난 SAFE 항목 ${actions.length}개를 복구합니다. 채널 이동·권한 overwrite·역할·Developer Portal 설정은 자동 변경하지 않습니다.`);if(!approval)return;discordPolicyLoading=true;renderDiscordPolicy();const payload=await request('/api/discord-policy/restore',approval);discordPolicyData=payload.policy;syncPolicyMonitorSnapshot();discordAuditData=payload.result.audit;discordFixData=payload.result.plan;renderDiscordAudit();renderDiscordFix();renderDiscordPolicy();const failed=payload.result.failed?.length||0;notice(failed?'일부 SAFE 복구가 실패했습니다. 남은 항목을 확인하세요.':'Discord 기준선 SAFE 복구를 완료했습니다.',Boolean(failed));}catch(error){notice(error.message,true);}finally{discordPolicyLoading=false;renderDiscordPolicy();}}

function renderRecovery(){
 const points=recoveryData.restorePoints||[],audit=recoveryData.auditLog||[],counts=selfCheckData?.counts;
 if($('recoveryPass'))$('recoveryPass').textContent=counts?String(counts.pass):'—';if($('recoveryWarn'))$('recoveryWarn').textContent=counts?String(counts.warn):'—';if($('recoveryFail'))$('recoveryFail').textContent=counts?String(counts.fail):'—';if($('restorePointCount'))$('restorePointCount').textContent=String(points.length);if($('restorePointBadge'))$('restorePointBadge').textContent=`${points.length} / 10`;
 if($('selfCheckBadge')){$('selfCheckBadge').textContent=!selfCheckData?'아직 점검 안 함':counts.fail?`오류 ${counts.fail}건`:counts.warn?`경고 ${counts.warn}건`:'정상';$('selfCheckBadge').classList.toggle('warn',Boolean(counts?.warn||counts?.fail));}
 if($('selfCheckList'))$('selfCheckList').innerHTML=selfCheckData?.checks?.length?selfCheckData.checks.map(c=>`<div class="check-row ${esc(c.status)}"><span class="check-icon">${c.status==='pass'?'✓':c.status==='warn'?'!':'×'}</span><div><strong>${esc(c.label)}</strong><small>${esc(c.detail||'')}</small></div></div>`).join(''):'<p class="empty">점검을 실행하면 결과가 표시됩니다.</p>';
 if($('restorePointList'))$('restorePointList').innerHTML=points.length?points.map(p=>`<div class="restore-row"><div><strong>${esc(p.label)}</strong><small>${esc(new Date(p.createdAt).toLocaleString('ko-KR'))} · 참가자 ${p.recordCount}명 · Revision ${p.revision} · ${p.integrity?'무결성 정상':'무결성 오류'}</small></div><div class="button-row"><button class="secondary compact" data-restore-point="${esc(p.id)}" ${busy||!p.integrity?'disabled':''}>복원</button><button class="secondary compact" data-delete-point="${esc(p.id)}" ${busy?'disabled':''}>삭제</button></div></div>`).join(''):'<p class="empty">복원 지점이 없습니다. 현재 상태를 먼저 저장해 주세요.</p>';
 const category=$('auditCategory')?.value||'all',filteredAudit=audit.filter(a=>category==='all'||a.category===category);if($('auditCount'))$('auditCount').textContent=`${audit.length}건`;if($('auditLog'))$('auditLog').innerHTML=filteredAudit.length?filteredAudit.slice(0,150).map(a=>{const details=a.details?Object.entries(a.details).map(([k,v])=>`${esc(k)}=${esc(v)}`).join(' · '):'';return `<div class="audit-row"><div><span class="audit-category">${esc(a.category)}</span><strong>${esc(a.summary)}</strong><small>${esc(new Date(a.at).toLocaleString('ko-KR'))} · ${esc(a.actor||'dashboard')}${details?` · ${details}`:''}</small></div></div>`;}).join(''):'<p class="empty">해당 분류의 감사 로그가 없습니다.</p>';
 renderSafeDeploy();
}
function renderSafeDeploy(){
 const data=safeDeployData,badge=$('safeDeployBadge');if(!badge)return;
 if(!data){badge.textContent='상태 확인 중';badge.classList.remove('warn');$('deployVersion').textContent='—';$('deploySchema').textContent='—';$('deployPostCheck').textContent='—';$('migrationPreview').innerHTML='<p class="empty">마이그레이션 상태를 불러오는 중…</p>';$('settingsDiff').innerHTML='<p class="empty">업데이트 기준점을 불러오는 중…</p>';$('applyMigration').disabled=true;return;}
 const post=data.update?.postUpdateCheck;badge.textContent=data.migration?.needed?'마이그레이션 필요':post?.status==='fail'?'업데이트 점검 오류':post?.status==='warn'?'업데이트 점검 경고':'보호 활성';badge.classList.toggle('warn',Boolean(data.migration?.needed||post?.status==='warn'||post?.status==='fail'));
 $('deployVersion').textContent=data.version||'—';$('deploySchema').textContent=`v${data.currentSchema||1} / v${data.dataSchemaVersion||'—'}`;$('deployPostCheck').textContent=post?`${String(post.status).toUpperCase()} · ${post.pass||0}/${post.warn||0}/${post.fail||0}`:'기록 없음';
 const migration=data.migration||{needed:false,changes:[]};$('applyMigration').disabled=busy||!migration.needed;$('migrationPreview').innerHTML=migration.needed?(migration.changes||[]).map(change=>`<div class="check-row warn"><span class="check-icon">!</span><div><strong>마이그레이션 변경</strong><small>${esc(change)}</small></div></div>`).join(''):`<div class="check-row pass"><span class="check-icon">✓</span><div><strong>데이터 스키마 최신</strong><small>현재 schema v${esc(data.currentSchema)} · 추가 마이그레이션이 필요하지 않습니다.</small></div></div>`;
 const diff=data.settingsDiff||[];$('settingsDiff').innerHTML=diff.length?diff.map(item=>`<div class="diff-row"><code class="diff-path">${esc(item.path)}</code><code>${esc(item.before)}</code><span class="diff-arrow">→</span><code>${esc(item.after)}</code></div>`).join(''):`<p class="empty">${data.baseline?'업데이트 기준점 이후 설정 변경이 없습니다.':'업데이트 전 자동 복원 지점이 없어 비교 기준이 없습니다.'}</p>`;
}
async function safeDeployRefresh(){try{safeDeployData=await request('/api/safe-deploy');renderSafeDeploy();}catch(error){notice(error.message,true);}}
async function prepareGuard(action,payload,message){const approval=await request('/api/guard/prepare',{action,...payload}),typed=prompt(`${message}

2단계 승인 문구: ${approval.phrase}
2분 안에 위 문구를 정확히 입력하세요.`);if(typed!==approval.phrase){notice('2단계 승인을 취소했습니다.',true);return null;}return {approvalId:approval.approvalId,approvalPhrase:typed};}
async function recoveryRefresh(){if(recoveryLoading)return;recoveryLoading=true;try{[recoveryData,safeDeployData]=await Promise.all([request('/api/recovery'),request('/api/safe-deploy')]);renderRecovery();}catch(error){notice(error.message,true);}finally{recoveryLoading=false;}}
async function runSelfCheck(){if(busy)return;busy=true;renderRecovery();try{selfCheckData=await request('/api/self-check');renderRecovery();notice(selfCheckData.counts.fail?'Self-Check에서 오류 항목을 발견했습니다.':selfCheckData.counts.warn?'Self-Check가 완료됐습니다. 경고 항목을 확인하세요.':'Self-Check가 모두 정상입니다.',Boolean(selfCheckData.counts.fail));}catch(error){notice(error.message,true);}finally{busy=false;renderRecovery();}}
async function createCheckpoint(){if(busy)return;busy=true;renderRecovery();try{const data=await request('/api/recovery/checkpoint',{label:$('checkpointLabel').value.trim()||'수동 복원 지점'});recoveryData=data;$('checkpointLabel').value='';renderRecovery();notice('현재 참가자·운영 상태를 복원 지점으로 저장했습니다.');}catch(error){notice(error.message,true);}finally{busy=false;renderRecovery();}}
async function restorePoint(id){const point=(recoveryData.restorePoints||[]).find(p=>p.id===id);if(!point||busy)return;try{const approval=await prepareGuard('restore-point',{targetId:id},`\"${point.label}\" 상태로 복원합니다. 현재 상태는 자동 보호됩니다.`);if(!approval)return;busy=true;renderRecovery();const data=await request('/api/recovery/restore',{id,...approval});accept(data);recoveryData=data.recovery||recoveryData;verifiedBackup=null;renderBackupVerification(null);await Promise.all([runSelfCheckAfterRestore(),safeDeployRefresh()]);notice(data.message||'복원 지점을 적용했습니다.');}catch(error){notice(error.message,true);}finally{busy=false;renderRecovery();}}
async function deleteRestorePoint(id){const point=(recoveryData.restorePoints||[]).find(p=>p.id===id);if(!point||busy)return;try{const approval=await prepareGuard('delete-restore-point',{targetId:id},`복원 지점 \"${point.label}\"을 영구 삭제합니다.`);if(!approval)return;busy=true;renderRecovery();recoveryData=await request('/api/recovery/delete',{id,...approval});await safeDeployRefresh();renderRecovery();notice('복원 지점을 삭제했습니다.');}catch(error){notice(error.message,true);}finally{busy=false;renderRecovery();}}
function renderBackupVerification(result){const badge=$('backupVerifyBadge'),box=$('backupVerifyResult');if(!badge||!box)return;if(!result){badge.textContent='검증 대기';badge.classList.remove('warn');box.innerHTML='<p class="empty">백업 파일을 선택해 주세요.</p>';$('restoreBackup').disabled=true;return;}badge.textContent=result.ok?'검증 통과':'검증 실패';badge.classList.toggle('warn',!result.ok);box.innerHTML=(result.checks||[]).map(c=>`<div class="check-row ${esc(c.status)}"><span class="check-icon">${c.status==='pass'?'✓':c.status==='warn'?'!':'×'}</span><div><strong>${esc(c.label)}</strong><small>${esc(c.detail||'')}</small></div></div>`).join('');$('restoreBackup').disabled=!result.ok;}
async function verifyBackupFile(){const file=$('backupVerifyFile').files?.[0];verifiedBackup=null;if(!file){renderBackupVerification(null);notice('검증할 JSON 백업 파일을 선택해 주세요.',true);return;}if(file.size>2*1024*1024){notice('전체 백업 파일은 2MB 이하만 검증할 수 있습니다.',true);return;}try{const bundle=JSON.parse(await file.text()),result=await request('/api/backup/verify',bundle);verifiedBackup=result.ok?bundle:null;renderBackupVerification(result);await recoveryRefresh();notice(result.ok?'백업 검증을 통과했습니다. 복원 전 현재 상태가 자동 보호됩니다.':'백업 검증에 실패했습니다. 오류 항목을 확인하세요.',!result.ok);}catch(error){renderBackupVerification({ok:false,checks:[{status:'fail',label:'JSON 파일 읽기',detail:error instanceof SyntaxError?'JSON 문법이 올바르지 않습니다.':error.message}]});notice(error instanceof SyntaxError?'JSON 파일 형식을 확인해 주세요.':error.message,true);}}
async function restoreVerifiedBackup(){if(!verifiedBackup||busy)return;try{const approval=await prepareGuard('restore-backup',{bundle:verifiedBackup},'검증된 전체 백업으로 참가자·운영 데이터를 복원합니다. 현재 상태는 자동 보호됩니다.');if(!approval)return;busy=true;renderRecovery();const data=await request('/api/backup/restore',{bundle:verifiedBackup,...approval});accept(data);recoveryData=data.recovery||recoveryData;verifiedBackup=null;$('backupVerifyFile').value='';renderBackupVerification(null);await Promise.all([runSelfCheckAfterRestore(),safeDeployRefresh()]);notice(data.message||'전체 백업을 복원했습니다.');}catch(error){notice(error.message,true);}finally{busy=false;renderRecovery();}}
async function applyPendingMigration(){if(!safeDeployData?.migration?.needed||busy)return;try{const approval=await prepareGuard('apply-migration',{},`운영 데이터 schema v${safeDeployData.migration.from} → v${safeDeployData.migration.to} 마이그레이션을 적용합니다. 적용 전 복원 지점이 자동 생성됩니다.`);if(!approval)return;busy=true;renderRecovery();const data=await request('/api/safe-deploy/migrate',approval);accept(data);await Promise.all([recoveryRefresh(),runSelfCheckAfterRestore()]);notice('데이터 마이그레이션을 적용하고 자동 보호 지점을 생성했습니다.');}catch(error){notice(error.message,true);}finally{busy=false;renderRecovery();}}
