function connectLive(){
 if(liveReconnectTimer){clearTimeout(liveReconnectTimer);liveReconnectTimer=null;}
 if(!('EventSource' in window)){liveSource?.close();liveSource=null;liveStatus('polling','자동 새로고침');return;}
 liveSource?.close();lastLiveEventAt=0;liveDelayMs=null;liveStatus('connecting','실시간 연결 중');
 const source=new EventSource('/api/events');liveSource=source;
 source.addEventListener('open',()=>{if(liveSource===source){if(liveOpenCount>0)reportRuntimeMetric('sse-reconnect');liveOpenCount++;lastLiveEventAt=Date.now();liveStatus('live','실시간 연결됨');}});
 source.addEventListener('snapshot',event=>{if(liveSource!==source)return;try{const data=JSON.parse(event.data);markLiveEvent(data.serverTime);accept(data);liveStatus('live','실시간 연결됨');}catch{}});
 source.addEventListener('heartbeat',event=>{if(liveSource!==source)return;try{const data=JSON.parse(event.data);if(data.version)appVersion=String(data.version);if(data.revision!==undefined)serverRevision=Number(data.revision)||0;markLiveEvent(data.serverTime);liveStatus('live','실시간 연결됨');}catch{}});
 source.addEventListener('error',()=>{if(liveSource===source){if(Date.now()-lastSseErrorReportAt>10000){lastSseErrorReportAt=Date.now();reportRuntimeMetric('sse-error');}liveStatus('offline','재연결 중');}});
}

function preview(){$('previewTitle').textContent=$('recruitTitle').value;$('previewDescription').textContent=$('recruitDescription').value;$('previewCount').textContent=`선정 ${$('rosterCount').value}명 · ${Number($('closeMinutes').value)>0?$('closeMinutes').value+'분 뒤 자동 마감':'직접 마감'}`;$('rosterMode').disabled=$('rosterGame').value==='er';}
function setupDrawOptions(){$('raceTrack').innerHTML=TRACKS.map(m=>`<option value="${esc(m.id)}">${esc(m.name)} · ${esc(m.difficulty||'보통')}</option>`).join('');syncDrawOptions(true);}
function syncDrawOptions(setTrackDefault=false){const mode=$('game').value,race=mode==='race';$('drawOptions').hidden=!race;$('raceTrackWrap').hidden=!race;$('raceLapsWrap').hidden=!race;if(race&&setTrackDefault){const track=TRACKS.find(t=>t.id===$('raceTrack').value);if(track)$('raceLaps').value=String(track.defaultLaps||3);}if(race){const track=TRACKS.find(t=>t.id===$('raceTrack').value);$('drawRuleSummary').textContent=`${track?.name||'서킷'} · ${$('raceLaps').value}랩 · 난이도 ${track?.difficulty||'보통'} · 공통 부스트 패드 ${(track?.boostZones||[]).length}곳`;}else $('drawRuleSummary').textContent=mode==='ladder'?'사다리 경로를 무작위로 생성해 결과를 결정합니다.':'서버에서 즉시 무작위 추첨합니다.';director.preview(directorConfig());}

function sessionDerived(){const s=state.session;const applicants=s?.applicants||[];const postponed=s?.postponed||[];const ready=applicants.filter(id=>!postponed.includes(id)&&hasGame(id,s?.game));const missing=applicants.filter(id=>!postponed.includes(id)&&!hasGame(id,s?.game));const pending=(s?.winners||[]).filter(id=>!(s?.confirmed||[]).includes(id));return {s,applicants,postponed,ready,missing,pending,active:Boolean(s&&s.phase!=='ended')};}
function currentPhaseIndex(s){if(!s)return -1;if(s.phase==='ended')return 5;if((s.teams||[]).length)return 4;if(s.phase==='checking'&&s.winners?.length&&s.winners.every(id=>s.confirmed?.includes(id)))return 4;return {open:0,closed:1,drawn:2,checking:3}[s.phase]??0;}

function renderBroadcastPreflight(){
 if(!$('preflightHero'))return;const data=broadcastPreflight||{},counts=data.counts||{},status=['pass','warn','fail'].includes(data.status)?data.status:'warn',labels={pass:'READY',warn:'CHECK',fail:'BLOCKED'},statusText={pass:'방송 준비 완료',warn:'확인 후 방송 가능',fail:'방송 전 해결 필요'};
 $('preflightHero').dataset.status=status;$('preflightOverall').textContent=statusText[status]||'확인 필요';$('preflightPassCount').textContent=String(counts.pass||0);$('preflightWarnCount').textContent=String(counts.warn||0);$('preflightFailCount').textContent=String(counts.fail||0);$('preflightCheckedAt').textContent=data.checkedAt?`최근 점검 ${new Date(data.checkedAt).toLocaleTimeString('ko-KR')}`:'최근 점검 —';$('preflightSummary').textContent=data.summary||'Discord · CHZZK · 저장소 · 장애 · 시참 상태를 한 번에 확인합니다.';$('preflightBadge').textContent=labels[status]||'CHECK';$('preflightBadge').classList.toggle('warn',status!=='pass');$('preflightCheckCount').textContent=`${counts.total||data.checks?.length||0}개`;
 const rec=data.recommendation||{title:'방송 운영 준비',text:'상태를 다시 점검해 주세요.',target:'operate',label:'컨트롤 센터',tone:'primary'};$('preflightNextTitle').textContent=rec.title;$('preflightNextText').textContent=rec.text;$('preflightNext').dataset.tone=rec.tone||'primary';$('preflightNextButton').textContent=rec.label||'확인';$('preflightNextButton').dataset.homeNav=rec.target||'operate';
 const checks=Array.isArray(data.checks)?data.checks:[];$('preflightChecklist').innerHTML=checks.length?checks.map(item=>`<button class="preflight-check-row ${esc(item.status)}" data-home-nav="${esc(item.target||'preflight')}"><span class="preflight-check-icon">${item.status==='pass'?'✓':item.status==='warn'?'!':'×'}</span><span><strong>${esc(item.label)}</strong><small>${esc(item.detail||'')}</small></span><em>${item.status==='pass'?'정상':item.status==='warn'?'확인':'해결'}</em></button>`).join(''):'<p class="empty">점검 결과를 불러오는 중…</p>';
 if($('homePreflight'))$('homePreflight').textContent=status==='pass'?'READY':status==='warn'?`주의 ${counts.warn||0}`:`차단 ${counts.fail||0}`;
}
async function preflightRefresh(){try{broadcastPreflight=await request('/api/broadcast-preflight');renderBroadcastPreflight();renderDashboardHome();}catch(error){notice(error.message,true);}}

function runbookModel(){return buildBroadcastRunbookModel({runbook:broadcastOps?.runbook||{},session:state.session,chzzkLive,access:{role:'admin',capabilities:['broadcast']}});}
function renderBroadcastRunbook(){
 if(!$('runbookHero'))return;const model=runbookModel(),phaseLabels={pre:'방송 전',live:'방송 중',post:'방송 후'},phaseIcons={pre:'◌',live:'●',post:'✓'},alertLabels={pending:'알림 대기',sent:'Discord 알림 전송',failed:'Discord 알림 실패',suppressed:'알림 없음'};$('runbookHero').dataset.phase=model.activePhase;$('runbookTitle').textContent=model.title;$('runbookSummary').textContent=model.closed?`마감 완료 · ${model.closeout?.summary||'보관된 Runbook입니다.'}`:`현재 단계 ${phaseLabels[model.activePhase]} · ${model.progress.pending}개 대기 · ${model.handoffs.length}개 인수인계 기록${model.phaseReason?` · ${model.phaseReason}`:''}`;$('runbookProgress').textContent=`${model.percent}%`;$('runbookProgressDetail').textContent=`${model.progress.done+model.progress.skipped} / ${model.progress.total} 처리`;$('runbookDone').textContent=String(model.progress.done);$('runbookSkipped').textContent=String(model.progress.skipped);$('runbookOwner').textContent=model.currentOwner||model.createdBy||'미지정';$('runbookUpdatedAt').textContent=model.updatedAt?`최근 갱신 ${formatRunbookTime(model.updatedAt)}`:'아직 저장된 변경 없음';$('runbookHandoffCount').textContent=`${model.handoffs.length}건`;if($('runbookPhaseSource'))$('runbookPhaseSource').textContent=`자동 감지 · ${phaseLabels[model.activePhase]}${model.phaseSource?` · ${model.phaseSource}`:''}`;
 $('runbookPhases').innerHTML=model.phaseMeta.map(phase=>{const items=model.grouped[phase.id]||[],done=items.filter(item=>item.status==='done').length,skipped=items.filter(item=>item.status==='skipped').length;return `<section class="panel runbook-phase-card ${phase.id===model.activePhase?'active':''}"><div class="panel-heading"><div><p class="eyebrow">${esc(phase.eyebrow)}</p><h2>${phaseIcons[phase.id]} ${esc(phase.label)}</h2></div><span class="badge">${done+skipped}/${items.length}</span></div><div class="runbook-step-list">${items.map(item=>`<article class="runbook-step ${esc(item.status)}"><button type="button" class="runbook-step-toggle" data-runbook-step="${esc(item.id)}" data-runbook-status="${esc(item.status==='done'?'pending':'done')}" aria-label="${esc(item.title)} ${item.status==='done'?'대기로 되돌리기':'완료 처리'}" ${model.closed?'disabled':''}><span>${item.status==='done'?'✓':item.status==='skipped'?'–':'○'}</span></button><div><strong>${esc(item.title)}</strong><small>${esc(item.detail)}</small>${item.updatedAt?`<em>${esc(runbookStatusLabel(item.status))} · ${esc(item.updatedBy||'operator')} · ${esc(formatRunbookTime(item.updatedAt))}</em>`:''}</div><div class="runbook-step-actions"><button type="button" class="secondary compact" data-runbook-step="${esc(item.id)}" data-runbook-status="${item.status==='skipped'?'pending':'skipped'}" ${model.closed?'disabled':''}>${item.status==='skipped'?'되돌리기':'건너뜀'}</button></div></article>`).join('')}</div></section>`;}).join('');
 $('runbookHandoffHistory').innerHTML=model.handoffs.length?model.handoffs.slice(0,10).map(item=>`<article class="runbook-handoff-row"><div><strong>${esc(item.from||'operator')}${item.to?` → ${esc(item.to)}`:''}</strong><small>${esc(formatRunbookTime(item.at))} · ${esc(alertLabels[item.alertStatus]||'알림 없음')}</small></div><p>${esc(item.note||'메모 없이 담당자만 변경')}</p>${item.alertStatus==='failed'&&item.alertError?`<small>알림 실패 · ${esc(item.alertError)}</small>`:''}</article>`).join(''):'<p class="empty">인수인계 기록이 없습니다.</p>';
 if($('runbookActivity'))$('runbookActivity').innerHTML=model.activity.length?model.activity.slice(0,12).map(item=>`<article class="runbook-activity-row" data-type="${esc(item.type)}"><span class="activity-dot" aria-hidden="true"></span><div><strong>${esc(item.message)}</strong><small>${esc(item.source||'broadcast')}</small></div><time>${esc(formatRunbookTime(item.at))}</time></article>`).join(''):'<p class="empty">Runbook 활동 기록이 없습니다.</p>';
 if($('runbookCloseoutBadge'))$('runbookCloseoutBadge').textContent=model.closed?'마감 완료':model.canCloseout?'마감 가능':'진행 중';if($('runbookCloseoutHint'))$('runbookCloseoutHint').textContent=model.closed?`마감 ${formatRunbookTime(model.closedAt)} · ${model.closedBy||'operator'} · 이 Runbook은 읽기 전용입니다.`:model.progress.pending?`대기 항목 ${model.progress.pending}개를 완료하거나 건너뜀 처리해야 마감할 수 있습니다.`:model.activePhase!=='post'?'방송 종료 또는 시참 회차 종료가 감지되어 POST-LIVE 단계가 된 뒤 마감할 수 있습니다.':'모든 절차가 처리되었습니다. 방송/시참 종료 상태를 확인한 뒤 마감하세요.';if($('runbookCloseoutSummary'))$('runbookCloseoutSummary').innerHTML=model.closeout?`<article><strong>${esc(model.closeout.summary||'방송 마감 완료')}</strong><small>${model.closeout.generatedAt?esc(formatRunbookTime(model.closeout.generatedAt)):''}${model.closeout.nextOwner?` · 다음 담당 ${esc(model.closeout.nextOwner)}`:''}</small>${model.closeout.nextNote?`<p>${esc(model.closeout.nextNote)}</p>`:''}${model.closeout.schedule?`<small>다음 일정 · ${esc(model.closeout.schedule.title)} · ${esc(formatRunbookTime(model.closeout.schedule.startAt))}</small>`:''}</article>`:'<p class="empty">아직 마감되지 않았습니다.</p>';if($('runbookCloseout'))$('runbookCloseout').disabled=busy||!model.canCloseout;if($('runbookCloseoutNote'))$('runbookCloseoutNote').disabled=model.closed;if($('runbookSaveHandoff'))$('runbookSaveHandoff').disabled=busy||model.closed;
}
async function runbookRefresh(){try{const data=await request('/api/broadcast-runbook');broadcastOps={...broadcastOps,runbook:data.runbook};renderBroadcastRunbook();}catch(error){notice(error.message,true);}}
async function setRunbookStep(id,status){if(busy||!id)return;busy=true;render();try{const data=await request('/api/broadcast-runbook/step',{id,status});broadcastOps={...broadcastOps,runbook:data.runbook};renderBroadcastRunbook();notice(status==='done'?'Runbook 항목을 완료 처리했습니다.':status==='skipped'?'Runbook 항목을 건너뜀 처리했습니다.':'Runbook 항목을 대기로 되돌렸습니다.');}catch(error){notice(error.message,true);}finally{busy=false;render();}}
async function saveRunbookHandoff(){if(busy)return;const to=$('runbookHandoffTo').value.trim(),note=$('runbookHandoffNote').value.trim();if(!to&&!note)return notice('다음 담당자 또는 인수인계 메모를 입력해 주세요.',true);busy=true;render();try{const data=await request('/api/broadcast-runbook/handoff',{to,note});broadcastOps={...broadcastOps,runbook:data.runbook};$('runbookHandoffTo').value='';$('runbookHandoffNote').value='';markDirtyGroupClean('runbook-handoff');renderBroadcastRunbook();notice('운영자 인수인계를 저장했습니다.');}catch(error){notice(error.message,true);}finally{busy=false;render();}}
async function closeoutRunbook(){if(busy)return;const model=runbookModel();if(!model.canCloseout)return notice(model.closed?'이미 마감된 Runbook입니다.':'Runbook 마감 조건을 먼저 충족해 주세요.',true);if(!confirmHighRiskAction('방송 Runbook을 마감하고 읽기 전용으로 보관할까요? 마감 후 체크리스트와 인수인계를 수정할 수 없습니다.'))return;const note=$('runbookCloseoutNote')?.value.trim()||'';busy=true;render();try{const data=await request('/api/broadcast-runbook/closeout',{note});broadcastOps={...broadcastOps,runbook:data.runbook};if($('runbookCloseoutNote'))$('runbookCloseoutNote').value='';markDirtyGroupClean('runbook-closeout');renderBroadcastRunbook();notice(data.alreadyClosed?'이미 마감된 Runbook입니다.':'방송 Runbook을 마감하고 보관했습니다.');}catch(error){notice(error.message,true);}finally{busy=false;render();}}
async function startNewRunbook(){if(busy)return;const model=runbookModel();if(model.id&&!model.closed){if(!confirmHighRiskAction('현재 활성 Runbook을 보관하고 새 방송 Runbook을 시작할까요? 현재 Runbook은 아카이브에 보관됩니다.'))return;}const title=prompt('새 Runbook 이름을 입력해 주세요.',`방송 운영 Runbook · ${new Date().toLocaleDateString('ko-KR')}`);if(title===null)return;busy=true;render();try{const data=await request('/api/broadcast-runbook/new',{title:title.trim()||'방송 운영 Runbook'});broadcastOps={...broadcastOps,runbook:data.runbook};$('runbookHandoffTo').value='';$('runbookHandoffNote').value='';markDirtyGroupClean('runbook-handoff');renderBroadcastRunbook();notice('새 방송 Runbook을 시작했습니다.');}catch(error){notice(error.message,true);}finally{busy=false;render();}}

function broadcastArchiveSummaryText(report){const s=report.sessionStats||{},c=report.checklist||{};return `${report.title}\n기간: ${new Date(report.startedAt).toLocaleString('ko-KR')} ~ ${new Date(report.endedAt).toLocaleString('ko-KR')}\nRunbook: 완료 ${c.done} · 건너뜀 ${c.skipped} / ${c.total}\n시참: ${s.completed}회 · 신청 ${s.applicants} · 당첨 ${s.winners} · 참석 ${s.confirmed} · 노쇼 ${s.noShows}\nCHZZK: 시작 ${report.chzzk?.starts||0} · 종료 ${report.chzzk?.ends||0}${report.nextBroadcast?.owner?`\n다음 담당: ${report.nextBroadcast.owner}`:''}${report.nextBroadcast?.note?`\n다음 방송 메모: ${report.nextBroadcast.note}`:''}`;}
function renderBroadcastPerformance(){
 if(!$('broadcastPerformanceTrend'))return;const range=Number($('broadcastPerformanceRange')?.value||5),model=buildBroadcastPerformanceModel(broadcastArchive.reports||[],{range}),aggregate=model.aggregate||{},comparison=model.comparison;
 $('broadcastPerformanceBroadcasts').textContent=String(aggregate.broadcasts||0);$('broadcastPerformanceApps').textContent=aggregate.applicantsPerSession?`${aggregate.applicantsPerSession}명`:'0명';$('broadcastPerformanceAttendance').textContent=`${aggregate.attendanceRate||0}%`;$('broadcastPerformanceNoShow').textContent=`${aggregate.noShowRate||0}%`;$('broadcastPerformancePace').textContent=aggregate.minutesPerSession?`${aggregate.minutesPerSession}분`:'0분';
 const trend=model.trend||[],maxApps=Math.max(1,...trend.map(item=>item.applicantsPerSession||0));$('broadcastPerformanceTrend').innerHTML=trend.length?trend.map(item=>`<article class="performance-trend-row"><div><strong>${esc(item.title)}</strong><small>${esc(new Date(item.endedAt).toLocaleDateString('ko-KR'))} · ${item.sessions}회차</small></div><div class="performance-trend-bars"><span><em>회차당 신청</em><i style="--bar:${Math.min(100,Math.round((item.applicantsPerSession/maxApps)*100))}%"></i><b>${item.applicantsPerSession}명</b></span><span><em>참석률</em><i style="--bar:${Math.min(100,item.attendanceRate)}%"></i><b>${item.attendanceRate}%</b></span><span><em>노쇼율</em><i style="--bar:${Math.min(100,item.noShowRate)}%"></i><b>${item.noShowRate}%</b></span></div></article>`).join(''):'<p class="empty">비교할 종료 방송이 없습니다.</p>';
 const labels={applicantsPerSession:'회차당 신청',attendanceRate:'당첨자 참석률',noShowRate:'당첨자 노쇼율',minutesPerSession:'회차당 Runbook 시간'};$('broadcastPerformanceCompare').innerHTML=comparison?.previous?comparison.metrics.map(metric=>{const delta=Number(metric.delta||0),sign=delta>0?'+':'';return `<article><span>${esc(labels[metric.key]||metric.key)}</span><strong>${metric.current}${esc(metric.unit)}</strong><small>직전 ${metric.previous}${esc(metric.unit)} · ${sign}${delta}${metric.unit==='%'?'%p':metric.unit}</small></article>`;}).join(''):'<p class="empty">직전 방송과 비교하려면 종료 방송이 2개 이상 필요합니다.</p>';
 $('broadcastPerformanceInsights').innerHTML=model.insights.map(item=>`<article class="performance-insight ${esc(item.tone)}"><strong>${esc(item.title)}</strong><p>${esc(item.detail)}</p></article>`).join('');
}
function renderBroadcastArchive(){if(!$('broadcastArchiveList'))return;const reports=broadcastArchive.reports||[],filtered=filterBroadcastArchive(reports,{query:$('broadcastArchiveQuery')?.value||''});$('broadcastArchiveCount').textContent=String(reports.length);$('broadcastArchiveSessions').textContent=String(reports.reduce((n,r)=>n+(r.sessionStats?.completed||0),0));$('broadcastArchiveApplicants').textContent=String(reports.reduce((n,r)=>n+(r.sessionStats?.applicants||0),0));$('broadcastArchiveNoShows').textContent=String(reports.reduce((n,r)=>n+(r.sessionStats?.noShows||0),0));$('broadcastArchiveGenerated').textContent=broadcastArchive.generatedAt?`갱신 ${new Date(broadcastArchive.generatedAt).toLocaleTimeString('ko-KR')}`:'대기';$('broadcastArchiveList').innerHTML=filtered.length?filtered.map(report=>{const s=report.sessionStats||{},games=s.games||{},next=report.nextBroadcast||{};return `<article class="broadcast-report-card"><div class="broadcast-report-head"><div><span class="badge">CLOSED</span><h3>${esc(report.title)}</h3><small>${esc(new Date(report.endedAt).toLocaleString('ko-KR'))} · ${esc(String(report.durationMinutes))}분</small></div><div class="button-row"><button class="secondary compact" data-broadcast-report-copy="${esc(report.id)}">요약 복사</button><button class="secondary compact" data-broadcast-report-download="${esc(report.id)}">JSON 내보내기</button></div></div><p>${esc(report.summary||'방송 마감 보고서')}</p><div class="broadcast-report-stats"><span><strong>${s.completed||0}</strong>회차</span><span><strong>${s.applicants||0}</strong>신청</span><span><strong>${s.winners||0}</strong>당첨</span><span><strong>${s.confirmed||0}</strong>참석</span><span><strong>${s.noShows||0}</strong>노쇼</span></div><div class="broadcast-report-games"><small>게임 · 칼바람 ${games.aram||0} / 협곡 ${games.rift||0} / 이터널 리턴 ${games.er||0}</small><small>Runbook · 완료 ${report.checklist?.done||0} / 건너뜀 ${report.checklist?.skipped||0} / 총 ${report.checklist?.total||0}</small><small>CHZZK · 시작 ${report.chzzk?.starts||0} / 종료 ${report.chzzk?.ends||0}</small></div>${next.owner||next.note||next.schedule?`<div class="broadcast-report-next"><strong>다음 방송 인수인계</strong>${next.owner?`<small>담당 · ${esc(next.owner)}</small>`:''}${next.schedule?`<small>일정 · ${esc(next.schedule.title)} · ${esc(new Date(next.schedule.startAt).toLocaleString('ko-KR'))}</small>`:''}${next.note?`<p>${esc(next.note)}</p>`:''}</div>`:''}</article>`}).join(''):'<p class="empty">조건에 맞는 종료 방송 보고서가 없습니다.</p>';renderBroadcastPerformance();}
async function broadcastArchiveRefresh(){try{broadcastArchive=normalizeBroadcastArchive(await request('/api/broadcast-archive'));renderBroadcastArchive();}catch(error){notice(error.message,true);if($('broadcastArchiveList'))$('broadcastArchiveList').innerHTML='<p class="empty">방송 아카이브를 불러오지 못했습니다.</p>';}}
async function copyBroadcastReport(id){const report=(broadcastArchive.reports||[]).find(item=>item.id===id);if(!report)return;try{await navigator.clipboard.writeText(broadcastArchiveSummaryText(report));notice('방송 보고서 요약을 복사했습니다.');}catch{notice('클립보드 복사에 실패했습니다.',true);}}
